//! Desktop theme (`rf-theme`). The native Rust/GPUI app can't import the React
//! `@reelforge/ui-kit`, so this crate mirrors its framework-free `tokens.json`
//! as Rust constants — generated by `scripts/gen_rf_theme.mjs` into `palette.rs`
//! so all four apps (web/electron/mobile/desktop) share ONE palette. Pure; the
//! generated palette is drift-guarded in CI (`gen_rf_theme.mjs --check`).

/// 24-bit RGB color. Helpers cover the formats GPUI / CSS need.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Rgb(pub u8, pub u8, pub u8);

impl Rgb {
    /// `0xRRGGBB` packed integer.
    pub const fn hex(self) -> u32 {
        ((self.0 as u32) << 16) | ((self.1 as u32) << 8) | (self.2 as u32)
    }

    /// `#rrggbb` CSS string.
    pub fn css(self) -> String {
        format!("#{:02x}{:02x}{:02x}", self.0, self.1, self.2)
    }

    /// Normalized `[r, g, b, a]` floats in `0.0..=1.0` (GPUI/wgpu-friendly).
    pub fn rgba_f32(self, alpha: f32) -> [f32; 4] {
        [
            self.0 as f32 / 255.0,
            self.1 as f32 / 255.0,
            self.2 as f32 / 255.0,
            alpha,
        ]
    }
}

pub mod palette {
    //! Generated palette from the ui-kit tokens (palette.rs imports Rgb itself).
    include!("palette.rs");
}

#[cfg(test)]
mod tests {
    use super::palette;
    use super::Rgb;

    #[test]
    fn primary_matches_shared_palette() {
        // #6a5bff — the one ReelForge brand color across all four apps.
        assert_eq!(palette::PRIMARY, Rgb(0x6a, 0x5b, 0xff));
        assert_eq!(palette::PRIMARY.hex(), 0x6a5bff);
        assert_eq!(palette::PRIMARY.css(), "#6a5bff");
    }

    #[test]
    fn surfaces_and_spacing_present() {
        assert_eq!(palette::BG, Rgb(0x0b, 0x0b, 0x12));
        assert_eq!(palette::SPACING_MD, 12);
        assert_eq!(palette::RADIUS_LG, 12);
    }

    #[test]
    fn rgba_f32_normalizes() {
        let [r, g, b, a] = Rgb(255, 0, 51).rgba_f32(1.0);
        assert!((r - 1.0).abs() < 1e-6 && g == 0.0 && (b - 0.2).abs() < 0.01 && a == 1.0);
    }

    #[test]
    fn platform_brand_colors_present() {
        assert_eq!(palette::PLATFORM_YOUTUBE, Rgb(0xff, 0x00, 0x00));
    }
}
